/**
 * TotalReclaw Plugin - HTTP API Client
 *
 * Communicates with the TotalReclaw server over JSON/HTTP. Uses Node.js
 * built-in `fetch` (available since Node 18).
 *
 * All authenticated endpoints expect:
 *   Authorization: Bearer <hex-encoded-auth-key>
 *
 * The server hashes the auth key with SHA-256 to look up the user.
 */

// ---------------------------------------------------------------------------
// Request / Response Types
// ---------------------------------------------------------------------------

/**
 * A single fact payload for the `/v1/store` endpoint.
 *
 * Field naming matches the server's `FactJSON` Pydantic model in
 * `server/src/handlers/store.py`.
 */
export interface StoreFactPayload {
  /** UUIDv7 fact identifier */
  id: string;
  /** ISO 8601 timestamp */
  timestamp: string;
  /** Hex-encoded AES-256-GCM ciphertext (iv || tag || ciphertext) */
  encrypted_blob: string;
  /** SHA-256 hashes of tokens for blind search */
  blind_indices: string[];
  /** Importance / decay score (0-10) */
  decay_score: number;
  /** Origin label */
  source: string;
  /** HMAC-SHA256 content fingerprint for dedup (hex) */
  content_fp?: string;
  /** Identifier of the creating agent */
  agent_id?: string;
  /** Hex-encoded AES-256-GCM encrypted embedding vector (PoC v2) */
  encrypted_embedding?: string;
}

/**
 * A search result candidate returned by `/v1/search`.
 *
 * Field naming matches the server's `SearchResultJSON` model.
 */
export interface SearchCandidate {
  fact_id: string;
  /** Hex-encoded AES-256-GCM ciphertext */
  encrypted_blob: string;
  decay_score: number;
  /** Unix milliseconds */
  timestamp: number;
  version: number;
  /** Hex-encoded AES-256-GCM encrypted embedding vector (PoC v2, optional) */
  encrypted_embedding?: string;
}

/**
 * A fact object returned by `/v1/export`.
 */
export interface ExportedFact {
  id: string;
  encrypted_blob: string;
  blind_indices: string[];
  decay_score: number;
  version: number;
  source: string;
  created_at: string;
  updated_at: string;
}

// ---------------------------------------------------------------------------
// API Client Factory
// ---------------------------------------------------------------------------

/**
 * Create an API client bound to a specific TotalReclaw server URL.
 *
 * All methods are async and throw descriptive errors on non-2xx responses.
 */
export function createApiClient(serverUrl: string) {
  // Normalise URL -- strip trailing slash.
  const baseUrl = serverUrl.replace(/\/+$/, '');

  // ------------------------------------------------------------------
  // Shared helpers
  // ------------------------------------------------------------------

  /**
   * Throw a descriptive error when the server returns a non-2xx status.
   */
  async function assertOk(res: Response, context: string): Promise<void> {
    if (res.ok) return;
    let body: string;
    try {
      body = await res.text();
    } catch {
      body = '(could not read response body)';
    }
    const hint = res.status === 401
      ? ' Authentication failed. If using a recovery phrase, check that all 12 words are in the correct order and spelled correctly.'
      : '';
    throw new Error(`${context}: HTTP ${res.status} - ${body}${hint}`);
  }

  // ------------------------------------------------------------------
  // Public methods
  // ------------------------------------------------------------------

  return {
    // ---- Registration (unauthenticated) ----

    /**
     * Register a new user.
     *
     * @param authKeyHash  Hex-encoded SHA-256 of the auth key (64 chars).
     * @param saltHex      Hex-encoded 32-byte salt (64 chars).
     * @returns `{ user_id }` on success.
     */
    async register(
      authKeyHash: string,
      saltHex: string,
    ): Promise<{ user_id: string }> {
      const res = await fetch(`${baseUrl}/v1/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ auth_key_hash: authKeyHash, salt: saltHex }),
      });
      await assertOk(res, 'register');
      const json = (await res.json()) as Record<string, unknown>;
      if (!json.success && json.error_code !== 'USER_EXISTS') {
        throw new Error(
          `register: server returned success=false - ${json.error_code}: ${json.error_message}`,
        );
      }
      if (!json.user_id) {
        throw new Error(
          `register: server did not return user_id (error_code=${json.error_code})`,
        );
      }
      return { user_id: json.user_id as string };
    },

    // ---- Store (authenticated) ----

    /**
     * Store one or more encrypted facts.
     *
     * @param userId       The authenticated user's ID.
     * @param facts        Array of `StoreFactPayload` objects.
     * @param authKeyHex   Hex-encoded raw auth key (64 chars) for Bearer header.
     */
    async store(
      userId: string,
      facts: StoreFactPayload[],
      authKeyHex: string,
    ): Promise<{ ids: string[]; duplicate_ids?: string[] }> {
      const res = await fetch(`${baseUrl}/v1/store`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${authKeyHex}`,
        },
        body: JSON.stringify({ user_id: userId, facts }),
      });
      await assertOk(res, 'store');
      const json = (await res.json()) as Record<string, unknown>;
      if (!json.success) {
        throw new Error(
          `store: server returned success=false - ${json.error_code}: ${json.error_message}`,
        );
      }
      return {
        ids: (json.ids as string[]) ?? [],
        duplicate_ids: json.duplicate_ids as string[] | undefined,
      };
    },

    // ---- Search (authenticated) ----

    /**
     * Search for facts using blind trapdoors.
     *
     * @param userId         The authenticated user's ID.
     * @param trapdoors      SHA-256 hex hashes of query tokens.
     * @param maxCandidates  Maximum candidates to retrieve.
     * @param authKeyHex     Hex-encoded raw auth key for Bearer header.
     * @returns Array of encrypted search candidates.
     */
    async search(
      userId: string,
      trapdoors: string[],
      maxCandidates: number,
      authKeyHex: string,
    ): Promise<SearchCandidate[]> {
      const res = await fetch(`${baseUrl}/v1/search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${authKeyHex}`,
        },
        body: JSON.stringify({
          user_id: userId,
          trapdoors,
          max_candidates: maxCandidates,
        }),
      });
      await assertOk(res, 'search');
      const json = (await res.json()) as Record<string, unknown>;
      if (!json.success) {
        throw new Error(
          `search: server returned success=false - ${json.error_code}: ${json.error_message}`,
        );
      }
      return (json.results as SearchCandidate[]) ?? [];
    },

    // ---- Delete (authenticated) ----

    /**
     * Soft-delete a fact by ID.
     *
     * @param factId      The fact UUID to delete.
     * @param authKeyHex  Hex-encoded raw auth key for Bearer header.
     */
    async deleteFact(factId: string, authKeyHex: string): Promise<void> {
      const res = await fetch(`${baseUrl}/v1/facts/${encodeURIComponent(factId)}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${authKeyHex}`,
        },
      });
      await assertOk(res, 'deleteFact');
      const json = (await res.json()) as Record<string, unknown>;
      if (!json.success) {
        throw new Error(
          `deleteFact: server returned success=false - ${json.error_code}: ${json.error_message}`,
        );
      }
    },

    // ---- Batch Delete (authenticated) ----

    /**
     * Batch soft-delete facts by ID list.
     *
     * @param factIds     Array of fact UUIDs to delete (max 500).
     * @param authKeyHex  Hex-encoded raw auth key for Bearer header.
     * @returns The number of facts that were actually deleted.
     */
    async batchDelete(factIds: string[], authKeyHex: string): Promise<number> {
      const res = await fetch(`${baseUrl}/v1/facts/batch-delete`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${authKeyHex}`,
        },
        body: JSON.stringify({ fact_ids: factIds }),
      });
      await assertOk(res, 'batchDelete');
      const json = (await res.json()) as Record<string, unknown>;
      if (!json.success) {
        throw new Error(
          `batchDelete: server returned success=false - ${json.error_code}: ${json.error_message}`,
        );
      }
      return (json.deleted_count as number) ?? 0;
    },

    // ---- Export (authenticated) ----

    /**
     * Export all active facts (paginated).
     *
     * @param authKeyHex  Hex-encoded raw auth key for Bearer header.
     * @param limit       Page size (default 1000, max 5000).
     * @param cursor      Cursor from previous page (omit for first page).
     * @returns Page of facts with pagination metadata.
     */
    async exportFacts(
      authKeyHex: string,
      limit: number = 1000,
      cursor?: string,
    ): Promise<{ facts: ExportedFact[]; cursor?: string; has_more: boolean; total_count?: number }> {
      const params = new URLSearchParams({ limit: String(limit) });
      if (cursor) params.set('cursor', cursor);

      const res = await fetch(`${baseUrl}/v1/export?${params.toString()}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${authKeyHex}`,
        },
      });
      await assertOk(res, 'exportFacts');
      const json = (await res.json()) as Record<string, unknown>;
      if (!json.success) {
        throw new Error(
          `exportFacts: server returned success=false - ${json.error_code}: ${json.error_message}`,
        );
      }
      return {
        facts: (json.facts as ExportedFact[]) ?? [],
        cursor: json.cursor as string | undefined,
        has_more: (json.has_more as boolean) ?? false,
        total_count: json.total_count as number | undefined,
      };
    },

    // ---- Health (unauthenticated) ----

    /**
     * Check server health.
     *
     * @returns `true` if the server responds with HTTP 200.
     */
    async health(): Promise<boolean> {
      try {
        const res = await fetch(`${baseUrl}/health`, { method: 'GET' });
        return res.status === 200;
      } catch {
        return false;
      }
    },
  };
}

/**
 * Unit tests for memory consolidation & near-duplicate detection.
 *
 * Run with: npx tsx consolidation.test.ts
 *
 * Uses TAP-style output (no test framework dependency).
 */

import {
  findNearDuplicate,
  shouldSupersede,
  clusterFacts,
  getStoreDedupThreshold,
  getConsolidationThreshold,
  STORE_DEDUP_MAX_CANDIDATES,
} from './consolidation.js';
import type { DecryptedCandidate } from './consolidation.js';

let passed = 0;
let failed = 0;
let testNum = 0;

function assert(condition: boolean, message: string): void {
  testNum++;
  if (condition) {
    passed++;
    console.log(`ok ${testNum} - ${message}`);
  } else {
    failed++;
    console.log(`not ok ${testNum} - ${message}`);
  }
}

function assertClose(actual: number, expected: number, epsilon: number, message: string): void {
  const diff = Math.abs(actual - expected);
  assert(diff < epsilon, `${message} (expected ~${expected}, got ${actual}, diff=${diff})`);
}

// Helper: create a DecryptedCandidate
function makeCandidate(
  overrides: Partial<DecryptedCandidate> & { id: string },
): DecryptedCandidate {
  return {
    text: `fact ${overrides.id}`,
    embedding: null,
    importance: 5,
    decayScore: 1.0,
    createdAt: 1000,
    version: 1,
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// getStoreDedupThreshold tests
// ---------------------------------------------------------------------------

console.log('# getStoreDedupThreshold');

{
  // Default threshold should be 0.85 (no env var set)
  const orig = process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  delete process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  assertClose(getStoreDedupThreshold(), 0.85, 1e-10, 'default threshold is 0.85');
  if (orig !== undefined) process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD = orig;
}

{
  // Custom threshold via env var
  const orig = process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD = '0.75';
  assertClose(getStoreDedupThreshold(), 0.75, 1e-10, 'custom threshold 0.75 from env');
  if (orig !== undefined) {
    process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD = orig;
  } else {
    delete process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  }
}

{
  // Invalid env var falls back to default
  const orig = process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD = 'not-a-number';
  assertClose(getStoreDedupThreshold(), 0.85, 1e-10, 'invalid env var falls back to 0.85');
  if (orig !== undefined) {
    process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD = orig;
  } else {
    delete process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  }
}

// ---------------------------------------------------------------------------
// getConsolidationThreshold tests
// ---------------------------------------------------------------------------

console.log('# getConsolidationThreshold');

{
  // Default threshold should be 0.88 (no env var set)
  const orig = process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  delete process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  assertClose(getConsolidationThreshold(), 0.88, 1e-10, 'default threshold is 0.88');
  if (orig !== undefined) process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD = orig;
}

{
  // Custom threshold via env var
  const orig = process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD = '0.95';
  assertClose(getConsolidationThreshold(), 0.95, 1e-10, 'custom threshold 0.95 from env');
  if (orig !== undefined) {
    process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD = orig;
  } else {
    delete process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  }
}

{
  // Invalid env var falls back to default
  const orig = process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD = 'garbage';
  assertClose(getConsolidationThreshold(), 0.88, 1e-10, 'invalid env var falls back to 0.88');
  if (orig !== undefined) {
    process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD = orig;
  } else {
    delete process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  }
}

// ---------------------------------------------------------------------------
// STORE_DEDUP_MAX_CANDIDATES constant
// ---------------------------------------------------------------------------

console.log('# STORE_DEDUP_MAX_CANDIDATES');

assert(STORE_DEDUP_MAX_CANDIDATES === 200, 'STORE_DEDUP_MAX_CANDIDATES is 200');

// ---------------------------------------------------------------------------
// findNearDuplicate tests
// ---------------------------------------------------------------------------

console.log('# findNearDuplicate');

{
  // Empty candidates -> null
  const result = findNearDuplicate([1, 0, 0], [], 0.85);
  assert(result === null, 'empty candidates returns null');
}

{
  // No embeddings on candidates -> null
  const candidates = [
    makeCandidate({ id: 'a', embedding: null }),
    makeCandidate({ id: 'b', embedding: null }),
  ];
  const result = findNearDuplicate([1, 0, 0], candidates, 0.85);
  assert(result === null, 'candidates without embeddings returns null');
}

{
  // Below threshold -> null
  const candidates = [
    makeCandidate({ id: 'a', embedding: [0, 1, 0] }), // orthogonal, cosine = 0
  ];
  const result = findNearDuplicate([1, 0, 0], candidates, 0.85);
  assert(result === null, 'below threshold returns null');
}

{
  // Above threshold -> returns match
  const candidates = [
    makeCandidate({ id: 'a', embedding: [1, 0, 0] }), // cosine = 1.0
  ];
  const result = findNearDuplicate([1, 0, 0], candidates, 0.85);
  assert(result !== null, 'above threshold returns match');
  assert(result!.existingFact.id === 'a', 'match is the correct candidate');
  assertClose(result!.similarity, 1.0, 1e-6, 'similarity is ~1.0');
}

{
  // Multiple matches -> returns highest similarity
  const candidates = [
    makeCandidate({ id: 'low', embedding: [0.86, Math.sqrt(1 - 0.86 * 0.86), 0] }), // cosine ~ 0.86
    makeCandidate({ id: 'high', embedding: [0.99, Math.sqrt(1 - 0.99 * 0.99), 0] }), // cosine ~ 0.99
    makeCandidate({ id: 'mid', embedding: [0.90, Math.sqrt(1 - 0.90 * 0.90), 0] }),  // cosine ~ 0.90
  ];
  const result = findNearDuplicate([1, 0, 0], candidates, 0.85);
  assert(result !== null, 'multiple matches: returns a match');
  assert(result!.existingFact.id === 'high', 'multiple matches: returns highest similarity');
}

{
  // Parallel vectors (cosine = 1.0) -> match
  const candidates = [
    makeCandidate({ id: 'parallel', embedding: [3, 6, 9] }), // parallel to [1, 2, 3]
  ];
  const result = findNearDuplicate([1, 2, 3], candidates, 0.85);
  assert(result !== null, 'parallel vectors: returns match');
  assertClose(result!.similarity, 1.0, 1e-6, 'parallel vectors: cosine is ~1.0');
}

{
  // Orthogonal vectors (cosine = 0) -> null
  const candidates = [
    makeCandidate({ id: 'ortho', embedding: [0, 1, 0] }),
  ];
  const result = findNearDuplicate([1, 0, 0], candidates, 0.85);
  assert(result === null, 'orthogonal vectors: returns null');
}

// ---------------------------------------------------------------------------
// shouldSupersede tests
// ---------------------------------------------------------------------------

console.log('# shouldSupersede');

{
  // Higher new importance -> supersede
  const existing = makeCandidate({ id: 'old', importance: 5 });
  const result = shouldSupersede(8, existing);
  assert(result === 'supersede', 'higher new importance -> supersede');
}

{
  // Lower new importance -> skip
  const existing = makeCandidate({ id: 'old', importance: 8 });
  const result = shouldSupersede(3, existing);
  assert(result === 'skip', 'lower new importance -> skip');
}

{
  // Equal importance -> supersede (newer wins)
  const existing = makeCandidate({ id: 'old', importance: 5 });
  const result = shouldSupersede(5, existing);
  assert(result === 'supersede', 'equal importance -> supersede (newer wins)');
}

// ---------------------------------------------------------------------------
// clusterFacts tests
// ---------------------------------------------------------------------------

console.log('# clusterFacts');

{
  // Empty facts -> empty clusters
  const clusters = clusterFacts([], 0.88);
  assert(clusters.length === 0, 'empty facts -> no clusters');
}

{
  // Single fact -> no clusters (needs at least 2 to form a cluster)
  const facts = [
    makeCandidate({ id: 'a', embedding: [1, 0, 0] }),
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 0, 'single fact -> no clusters');
}

{
  // Two identical embeddings -> one cluster
  const facts = [
    makeCandidate({ id: 'a', embedding: [1, 0, 0] }),
    makeCandidate({ id: 'b', embedding: [1, 0, 0] }),
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 1, 'two identical -> one cluster');
  assert(clusters[0].duplicates.length === 1, 'two identical -> one duplicate');
}

{
  // Two dissimilar embeddings -> no clusters
  const facts = [
    makeCandidate({ id: 'a', embedding: [1, 0, 0] }),
    makeCandidate({ id: 'b', embedding: [0, 1, 0] }), // orthogonal
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 0, 'two dissimilar -> no clusters');
}

{
  // Multiple clusters: two groups of duplicates + one unique
  const facts = [
    makeCandidate({ id: 'a1', embedding: [1, 0, 0] }),
    makeCandidate({ id: 'a2', embedding: [1, 0, 0] }),    // dup of a1
    makeCandidate({ id: 'b1', embedding: [0, 1, 0] }),
    makeCandidate({ id: 'b2', embedding: [0, 1, 0] }),    // dup of b1
    makeCandidate({ id: 'c1', embedding: [0, 0, 1] }),    // unique
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 2, 'multiple clusters: two groups found');
}

{
  // Facts without embeddings are not clustered
  const facts = [
    makeCandidate({ id: 'a', embedding: [1, 0, 0] }),
    makeCandidate({ id: 'b', embedding: null }),           // no embedding
    makeCandidate({ id: 'c', embedding: [1, 0, 0] }),     // dup of a
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 1, 'no-embedding facts skipped, one cluster of a+c');
  // b should not appear in any cluster
  const allIds = clusters.flatMap(c => [c.representative.id, ...c.duplicates.map(d => d.id)]);
  assert(!allIds.includes('b'), 'no-embedding fact not in any cluster');
}

{
  // Representative = highest importance (via decayScore tiebreak)
  const facts = [
    makeCandidate({ id: 'low', embedding: [1, 0, 0], decayScore: 0.5, importance: 3 }),
    makeCandidate({ id: 'high', embedding: [1, 0, 0], decayScore: 0.9, importance: 8 }),
    makeCandidate({ id: 'mid', embedding: [1, 0, 0], decayScore: 0.7, importance: 5 }),
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 1, 'representative test: one cluster');
  assert(clusters[0].representative.id === 'high', 'representative = highest decayScore');
  assert(clusters[0].duplicates.length === 2, 'two duplicates');
}

{
  // Tiebreak: same decayScore -> most recent (highest createdAt)
  const facts = [
    makeCandidate({ id: 'old', embedding: [1, 0, 0], decayScore: 1.0, createdAt: 1000 }),
    makeCandidate({ id: 'new', embedding: [1, 0, 0], decayScore: 1.0, createdAt: 2000 }),
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 1, 'tiebreak test: one cluster');
  assert(clusters[0].representative.id === 'new', 'tiebreak: most recent is representative');
}

{
  // Tiebreak: same decayScore + createdAt -> longest text
  const facts = [
    makeCandidate({ id: 'short', text: 'abc', embedding: [1, 0, 0], decayScore: 1.0, createdAt: 1000 }),
    makeCandidate({ id: 'long', text: 'abcdefghij', embedding: [1, 0, 0], decayScore: 1.0, createdAt: 1000 }),
  ];
  const clusters = clusterFacts(facts, 0.88);
  assert(clusters.length === 1, 'tiebreak longest text: one cluster');
  assert(clusters[0].representative.id === 'long', 'tiebreak: longest text is representative');
}

// ---------------------------------------------------------------------------
// Summary
// ---------------------------------------------------------------------------

console.log(`\n1..${testNum}`);
console.log(`# pass: ${passed}`);
console.log(`# fail: ${failed}`);

if (failed > 0) {
  console.log('\nFAILED');
  process.exit(1);
} else {
  console.log('\nALL TESTS PASSED');
  process.exit(0);
}

/**
 * TotalReclaw Plugin - Memory Consolidation & Near-Duplicate Detection
 *
 * Provides cross-session / cross-vault deduplication of stored facts using
 * cosine similarity on their embeddings. Unlike semantic-dedup.ts (which
 * handles within-batch dedup at threshold 0.9), this module handles:
 *
 *   1. Store-time dedup — before writing a new fact, check whether a
 *      near-duplicate already exists in the vault (findNearDuplicate).
 *   2. Supersede logic — when a near-duplicate is found, decide whether
 *      the new fact should replace or be skipped (shouldSupersede).
 *   3. Bulk consolidation — cluster all facts in the vault and identify
 *      groups of near-duplicates for cleanup (clusterFacts).
 *
 * This module intentionally has minimal dependencies (only reranker for
 * cosineSimilarity) so it can be tested without pulling in the full
 * plugin dependency graph.
 */

import { cosineSimilarity } from './reranker.js';

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/**
 * Get the cosine similarity threshold for store-time dedup.
 *
 * Configurable via TOTALRECLAW_STORE_DEDUP_THRESHOLD env var.
 * Must be a number in [0, 1]. Falls back to 0.85 if invalid or unset.
 */
export function getStoreDedupThreshold(): number {
  const envVal = process.env.TOTALRECLAW_STORE_DEDUP_THRESHOLD;
  if (envVal !== undefined) {
    const parsed = parseFloat(envVal);
    if (!isNaN(parsed) && parsed >= 0 && parsed <= 1) return parsed;
  }
  return 0.85;
}

/**
 * Get the cosine similarity threshold for bulk consolidation clustering.
 *
 * Configurable via TOTALRECLAW_CONSOLIDATION_THRESHOLD env var.
 * Must be a number in [0, 1]. Falls back to 0.88 if invalid or unset.
 */
export function getConsolidationThreshold(): number {
  const envVal = process.env.TOTALRECLAW_CONSOLIDATION_THRESHOLD;
  if (envVal !== undefined) {
    const parsed = parseFloat(envVal);
    if (!isNaN(parsed) && parsed >= 0 && parsed <= 1) return parsed;
  }
  return 0.88;
}

/** Maximum candidates to compare against during store-time dedup. */
export const STORE_DEDUP_MAX_CANDIDATES = 200;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** A decrypted fact candidate from the vault, with metadata for ranking. */
export interface DecryptedCandidate {
  id: string;
  text: string;
  embedding: number[] | null;
  importance: number;
  decayScore: number;
  createdAt: number;
  version: number;
}

/** A match result from near-duplicate detection. */
export interface NearDuplicateMatch {
  existingFact: DecryptedCandidate;
  similarity: number;
}

/** A cluster of near-duplicate facts for consolidation. */
export interface ConsolidationCluster {
  representative: DecryptedCandidate;
  duplicates: DecryptedCandidate[];
}

// ---------------------------------------------------------------------------
// Store-time dedup
// ---------------------------------------------------------------------------

/**
 * Find the best near-duplicate match for a new fact among existing candidates.
 *
 * Compares the new fact's embedding against all candidates using cosine
 * similarity. Returns the candidate with the highest similarity above the
 * threshold, or null if no match is found.
 *
 * Candidates without embeddings are skipped (fail-safe).
 *
 * @param newFactEmbedding - Embedding vector for the new fact
 * @param candidates       - Existing facts to compare against
 * @param threshold        - Cosine similarity threshold (e.g. 0.85)
 * @returns                - Best match above threshold, or null
 */
export function findNearDuplicate(
  newFactEmbedding: number[],
  candidates: DecryptedCandidate[],
  threshold: number,
): NearDuplicateMatch | null {
  let bestMatch: NearDuplicateMatch | null = null;

  for (const candidate of candidates) {
    if (!candidate.embedding || candidate.embedding.length === 0) continue;

    const similarity = cosineSimilarity(newFactEmbedding, candidate.embedding);
    if (similarity >= threshold) {
      if (!bestMatch || similarity > bestMatch.similarity) {
        bestMatch = { existingFact: candidate, similarity };
      }
    }
  }

  return bestMatch;
}

// ---------------------------------------------------------------------------
// Supersede logic
// ---------------------------------------------------------------------------

/**
 * Decide whether a new fact should supersede an existing near-duplicate.
 *
 * - Higher importance wins.
 * - Equal importance: new fact supersedes (newer is preferred).
 *
 * @param newImportance - Importance score of the new fact
 * @param existingFact  - The existing near-duplicate candidate
 * @returns             - 'supersede' if new fact should replace, 'skip' otherwise
 */
export function shouldSupersede(
  newImportance: number,
  existingFact: DecryptedCandidate,
): 'supersede' | 'skip' {
  if (newImportance >= existingFact.importance) return 'supersede';
  return 'skip';
}

// ---------------------------------------------------------------------------
// Bulk consolidation
// ---------------------------------------------------------------------------

/**
 * Pick the best representative from a group of near-duplicate facts.
 *
 * Tiebreak order:
 *   1. Highest decayScore
 *   2. Most recent (highest createdAt)
 *   3. Longest text
 */
function pickRepresentative(facts: DecryptedCandidate[]): DecryptedCandidate {
  let best = facts[0];
  for (let i = 1; i < facts.length; i++) {
    const f = facts[i];
    if (
      f.decayScore > best.decayScore ||
      (f.decayScore === best.decayScore && f.createdAt > best.createdAt) ||
      (f.decayScore === best.decayScore && f.createdAt === best.createdAt && f.text.length > best.text.length)
    ) {
      best = f;
    }
  }
  return best;
}

/**
 * Cluster facts by semantic similarity using greedy single-pass clustering.
 *
 * For each fact (in order), assigns it to the first existing cluster whose
 * representative has cosine similarity >= threshold. If no cluster matches,
 * a new cluster is started.
 *
 * Only returns clusters that have duplicates (i.e. more than one member).
 * Facts without embeddings are not clustered.
 *
 * @param facts     - All facts to cluster
 * @param threshold - Cosine similarity threshold (e.g. 0.88)
 * @returns         - Clusters with duplicates (representative + duplicates)
 */
export function clusterFacts(
  facts: DecryptedCandidate[],
  threshold: number,
): ConsolidationCluster[] {
  const clusters: { members: DecryptedCandidate[] }[] = [];

  for (const fact of facts) {
    if (!fact.embedding || fact.embedding.length === 0) continue;

    let assigned = false;
    for (const cluster of clusters) {
      // Compare against the first member's embedding (cluster seed)
      const seed = cluster.members[0];
      if (!seed.embedding) continue;

      const similarity = cosineSimilarity(fact.embedding, seed.embedding);
      if (similarity >= threshold) {
        cluster.members.push(fact);
        assigned = true;
        break;
      }
    }

    if (!assigned) {
      clusters.push({ members: [fact] });
    }
  }

  // Only return clusters with duplicates, pick representative for each
  const result: ConsolidationCluster[] = [];
  for (const cluster of clusters) {
    if (cluster.members.length < 2) continue;

    const representative = pickRepresentative(cluster.members);
    const duplicates = cluster.members.filter((m) => m !== representative);
    result.push({ representative, duplicates });
  }

  return result;
}

/**
 * TotalReclaw Plugin - Crypto Operations
 *
 * All cryptographic primitives used by the OpenClaw plugin. These must
 * produce byte-for-byte identical output to the TotalReclaw client library
 * (`client/src/crypto/`) so that memories written by one can be read by
 * the other.
 *
 * Key derivation chain:
 *   master_password + salt
 *     -> Argon2id(t=3, m=65536, p=4, dkLen=32) -> masterKey
 *     -> HKDF-SHA256(masterKey, salt, "totalreclaw-auth-key-v1",       32) -> authKey
 *     -> HKDF-SHA256(masterKey, salt, "totalreclaw-encryption-key-v1", 32) -> encryptionKey
 *     -> HKDF-SHA256(masterKey, salt, "openmemory-dedup-v1",          32) -> dedupKey
 *
 * Encryption: AES-256-GCM (12-byte IV, 16-byte tag)
 * Blind indices: SHA-256 of lowercase tokens
 * Content fingerprint: HMAC-SHA256(dedupKey, normalizeText(plaintext))
 */

import { argon2id } from '@noble/hashes/argon2.js';
import { hkdf } from '@noble/hashes/hkdf.js';
import { sha256 } from '@noble/hashes/sha2.js';
import { hmac } from '@noble/hashes/hmac.js';
import { mnemonicToSeedSync, validateMnemonic } from '@scure/bip39';
import { wordlist } from '@scure/bip39/wordlists/english.js';
import { stemmer } from 'porter-stemmer';
import crypto from 'node:crypto';

// ---------------------------------------------------------------------------
// Key Derivation
// ---------------------------------------------------------------------------

/** HKDF context strings -- must match client/src/crypto/kdf.ts exactly. */
const AUTH_KEY_INFO = 'totalreclaw-auth-key-v1';
const ENCRYPTION_KEY_INFO = 'totalreclaw-encryption-key-v1';
const DEDUP_KEY_INFO = 'openmemory-dedup-v1';

/** Argon2id parameters -- OWASP recommendations, matching client defaults. */
const ARGON2_TIME_COST = 3;
const ARGON2_MEMORY_COST = 65536; // 64 MB in KiB
const ARGON2_PARALLELISM = 4;
const ARGON2_DK_LEN = 32;

/** AES-256-GCM constants. */
const IV_LENGTH = 12;
const TAG_LENGTH = 16;
const KEY_LENGTH = 32;

/**
 * Check if the input looks like a BIP-39 mnemonic (12 or 24 words from the BIP-39 English wordlist).
 */
function isBip39Mnemonic(input: string): boolean {
  const words = input.trim().split(/\s+/);
  if (words.length !== 12 && words.length !== 24) return false;
  return validateMnemonic(input.trim(), wordlist);
}

/**
 * Derive encryption keys from a BIP-39 mnemonic.
 * Uses the 512-bit BIP-39 seed as HKDF input (NOT the derived private key)
 * for proper key separation from the Ethereum signing key.
 */
function deriveKeysFromMnemonic(
  mnemonic: string,
): { authKey: Buffer; encryptionKey: Buffer; dedupKey: Buffer; salt: Buffer } {
  // BIP-39: mnemonic -> 512-bit seed via PBKDF2(mnemonic, "mnemonic", 2048 rounds)
  const seed = mnemonicToSeedSync(mnemonic.trim());

  // Use first 32 bytes of seed as deterministic salt for HKDF
  // (BIP-39 mnemonics are self-salting via PBKDF2, no random salt needed)
  const salt = Buffer.from(seed.slice(0, 32));

  // HKDF-SHA256 from the full 512-bit seed, using distinct info strings
  const enc = (s: string) => Buffer.from(s, 'utf8');
  const seedBuf = Buffer.from(seed);

  const authKey = Buffer.from(
    hkdf(sha256, seedBuf, salt, enc(AUTH_KEY_INFO), 32),
  );
  const encryptionKey = Buffer.from(
    hkdf(sha256, seedBuf, salt, enc(ENCRYPTION_KEY_INFO), 32),
  );
  const dedupKey = Buffer.from(
    hkdf(sha256, seedBuf, salt, enc(DEDUP_KEY_INFO), 32),
  );

  return { authKey, encryptionKey, dedupKey, salt };
}

/**
 * Derive auth, encryption, and dedup keys from a recovery phrase.
 *
 * If the password is a valid BIP-39 mnemonic (12 or 24 words), keys are
 * derived from the 512-bit BIP-39 seed via HKDF. Otherwise, the legacy
 * Argon2id path is used.
 *
 * For the Argon2id path: if no salt is provided a fresh 32-byte random salt
 * is generated. Pass an existing salt when restoring a previously-registered
 * account so that the derived keys match the original registration.
 *
 * @returns Object containing authKey, encryptionKey, dedupKey, and salt (all Buffers).
 */
export function deriveKeys(
  password: string,
  existingSalt?: Buffer,
): { authKey: Buffer; encryptionKey: Buffer; dedupKey: Buffer; salt: Buffer } {
  // Auto-detect BIP-39 mnemonic vs arbitrary password
  if (isBip39Mnemonic(password)) {
    // BIP-39 path: mnemonic is self-salting, existingSalt is ignored for derivation
    // but we still return the deterministic salt for server registration
    return deriveKeysFromMnemonic(password);
  }

  // Legacy path: arbitrary password via Argon2id
  const salt = existingSalt ?? crypto.randomBytes(32);

  // Step 1 -- Argon2id to derive a 32-byte master key.
  // @noble/hashes argon2id accepts Uint8Array for both password and salt.
  const masterKey = argon2id(
    Buffer.from(password, 'utf8'),
    salt,
    { t: ARGON2_TIME_COST, m: ARGON2_MEMORY_COST, p: ARGON2_PARALLELISM, dkLen: ARGON2_DK_LEN },
  );

  // Step 2 -- HKDF-SHA256 for each sub-key using distinct info strings.
  // @noble/hashes v2 requires Uint8Array for info param.
  const enc = (s: string) => Buffer.from(s, 'utf8');
  const authKey = Buffer.from(
    hkdf(sha256, masterKey, salt, enc(AUTH_KEY_INFO), 32),
  );
  const encryptionKey = Buffer.from(
    hkdf(sha256, masterKey, salt, enc(ENCRYPTION_KEY_INFO), 32),
  );
  const dedupKey = Buffer.from(
    hkdf(sha256, masterKey, salt, enc(DEDUP_KEY_INFO), 32),
  );

  return { authKey, encryptionKey, dedupKey, salt: Buffer.from(salt) };
}

// ---------------------------------------------------------------------------
// LSH Seed Derivation
// ---------------------------------------------------------------------------

/**
 * HKDF context string for LSH seed derivation.
 *
 * The LSH hasher needs a deterministic seed so that the same master key
 * always generates the same random hyperplane matrices. We derive this seed
 * from the master key using HKDF with a unique info string.
 *
 * For the BIP-39 path the HKDF input is the 512-bit BIP-39 seed; for the
 * Argon2id path it is the 32-byte master key.
 */
const LSH_SEED_INFO = 'openmemory-lsh-seed-v1';

/**
 * Derive a 32-byte seed for the LSH hasher from the master key derivation
 * chain.
 *
 * Call this once during initialization and pass the result to `new LSHHasher(seed, dims)`.
 *
 * For the BIP-39 path we use the full 512-bit BIP-39 seed as IKM; for the
 * Argon2id path we use the 32-byte Argon2id-derived master key. In both
 * cases the salt from `deriveKeys()` is reused for domain separation.
 */
export function deriveLshSeed(
  password: string,
  salt: Buffer,
): Uint8Array {
  if (isBip39Mnemonic(password)) {
    const seed = mnemonicToSeedSync(password.trim());
    return new Uint8Array(
      hkdf(sha256, Buffer.from(seed), salt, Buffer.from(LSH_SEED_INFO, 'utf8'), 32),
    );
  }

  // Argon2id path: re-derive the master key, then HKDF with LSH info string.
  const masterKey = argon2id(
    Buffer.from(password, 'utf8'),
    salt,
    { t: ARGON2_TIME_COST, m: ARGON2_MEMORY_COST, p: ARGON2_PARALLELISM, dkLen: ARGON2_DK_LEN },
  );

  return new Uint8Array(
    hkdf(sha256, masterKey, salt, Buffer.from(LSH_SEED_INFO, 'utf8'), 32),
  );
}

// ---------------------------------------------------------------------------
// Auth Key Hash
// ---------------------------------------------------------------------------

/**
 * Compute the SHA-256 hash of the auth key.
 *
 * The server stores SHA256(authKey) during registration and uses it to look
 * up users on every request. The hex string returned here is what the plugin
 * sends to `/v1/register` as `auth_key_hash`.
 */
export function computeAuthKeyHash(authKey: Buffer): string {
  return Buffer.from(sha256(authKey)).toString('hex');
}

// ---------------------------------------------------------------------------
// AES-256-GCM Encrypt / Decrypt
// ---------------------------------------------------------------------------

/**
 * Encrypt a UTF-8 plaintext string with AES-256-GCM.
 *
 * Wire format (base64-encoded):
 *   [iv: 12 bytes][tag: 16 bytes][ciphertext: variable]
 *
 * This matches `serializeEncryptedData` in `client/src/crypto/aes.ts`.
 */
export function encrypt(plaintext: string, encryptionKey: Buffer): string {
  if (encryptionKey.length !== KEY_LENGTH) {
    throw new Error(`Invalid key length: expected ${KEY_LENGTH}, got ${encryptionKey.length}`);
  }

  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-gcm', encryptionKey, iv, {
    authTagLength: TAG_LENGTH,
  });

  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();

  // Combine: iv || tag || ciphertext  (same order as client library)
  const combined = Buffer.concat([iv, tag, ciphertext]);
  return combined.toString('base64');
}

/**
 * Decrypt a base64-encoded AES-256-GCM blob back to a UTF-8 string.
 *
 * Expects the wire format produced by `encrypt()` above.
 */
export function decrypt(encryptedBase64: string, encryptionKey: Buffer): string {
  if (encryptionKey.length !== KEY_LENGTH) {
    throw new Error(`Invalid key length: expected ${KEY_LENGTH}, got ${encryptionKey.length}`);
  }

  const combined = Buffer.from(encryptedBase64, 'base64');

  if (combined.length < IV_LENGTH + TAG_LENGTH) {
    throw new Error('Encrypted data too short');
  }

  const iv = combined.subarray(0, IV_LENGTH);
  const tag = combined.subarray(IV_LENGTH, IV_LENGTH + TAG_LENGTH);
  const ciphertext = combined.subarray(IV_LENGTH + TAG_LENGTH);

  const decipher = crypto.createDecipheriv('aes-256-gcm', encryptionKey, iv, {
    authTagLength: TAG_LENGTH,
  });
  decipher.setAuthTag(tag);

  const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return plaintext.toString('utf8');
}

// ---------------------------------------------------------------------------
// Blind Indices
// ---------------------------------------------------------------------------

/**
 * Generate blind indices (SHA-256 hashes of tokens) for a text string.
 *
 * Tokenization rules (must match `client/src/crypto/blind.ts#tokenize`):
 *   1. Lowercase
 *   2. Remove punctuation (keep Unicode letters, numbers, whitespace)
 *   3. Split on whitespace
 *   4. Filter tokens shorter than 2 characters
 *
 * Each surviving token is SHA-256 hashed and returned as a hex string.
 * The returned array is deduplicated.
 */
export function generateBlindIndices(text: string): string[] {
  const tokens = text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ') // Remove punctuation, keep letters/numbers
    .split(/\s+/)
    .filter((t) => t.length >= 2);

  const seen = new Set<string>();
  const indices: string[] = [];

  for (const token of tokens) {
    // Exact word hash (unchanged behavior).
    const hash = Buffer.from(sha256(Buffer.from(token, 'utf8'))).toString('hex');
    if (!seen.has(hash)) {
      seen.add(hash);
      indices.push(hash);
    }

    // Stemmed word hash. The stem is prefixed with "stem:" before hashing
    // to avoid collisions between a word that happens to equal another
    // word's stem (e.g., the word "commun" vs the stem of "community").
    const stem = stemmer(token);
    if (stem.length >= 2 && stem !== token) {
      const stemHash = Buffer.from(
        sha256(Buffer.from(`stem:${stem}`, 'utf8'))
      ).toString('hex');
      if (!seen.has(stemHash)) {
        seen.add(stemHash);
        indices.push(stemHash);
      }
    }
  }

  return indices;
}

// ---------------------------------------------------------------------------
// Content Fingerprint (Dedup)
// ---------------------------------------------------------------------------

/**
 * Normalize text for deterministic fingerprinting.
 *
 * Steps (matching `client/src/crypto/fingerprint.ts#normalizeText`):
 *   1. Unicode NFC normalization
 *   2. Lowercase
 *   3. Collapse whitespace (spaces/tabs/newlines to single space)
 *   4. Trim leading/trailing whitespace
 */
function normalizeText(text: string): string {
  return text
    .normalize('NFC')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Compute an HMAC-SHA256 content fingerprint for exact-duplicate detection.
 *
 * The server stores this fingerprint and uses it to reject duplicate writes
 * without ever seeing the plaintext.
 *
 * @returns 64-character hex string.
 */
export function generateContentFingerprint(plaintext: string, dedupKey: Buffer): string {
  const normalized = normalizeText(plaintext);
  return Buffer.from(
    hmac(sha256, dedupKey, Buffer.from(normalized, 'utf8')),
  ).toString('hex');
}

/**
 * TotalReclaw Plugin - Local Embedding via @huggingface/transformers
 *
 * Uses the Qwen3-Embedding-0.6B ONNX model to generate 1024-dimensional
 * text embeddings locally. No API key needed, no data leaves the machine.
 * Supports 100+ languages (EN, PT, ES, ZH, etc.).
 *
 * This preserves the E2EE guarantee: embeddings are generated
 * CLIENT-SIDE before encryption, so no plaintext ever reaches an external API.
 *
 * Model details:
 *   - Quantized (int8) ONNX model: ~600MB download on first use
 *   - Cached in ~/.cache/huggingface/ after first download
 *   - Lazy initialization: first call ~3-5s (model load), subsequent ~100ms
 *   - Output: 1024-dimensional normalized embedding vector
 *   - No instruction prefix needed (bare queries perform better)
 *
 * Dependencies: @huggingface/transformers (handles model download,
 * tokenization, ONNX inference, last-token pooling, and normalization).
 */

// @ts-ignore - @huggingface/transformers types may not be perfect
import { pipeline, type FeatureExtractionPipeline } from '@huggingface/transformers';

/** ONNX-optimized Qwen3-Embedding-0.6B from HuggingFace Hub. */
const MODEL_ID = 'onnx-community/Qwen3-Embedding-0.6B-ONNX';

/** Fixed output dimensionality for Qwen3-Embedding-0.6B. */
const EMBEDDING_DIM = 1024;

/** Lazily initialized feature extraction pipeline. */
let extractor: FeatureExtractionPipeline | null = null;

/**
 * Generate a 1024-dimensional embedding vector for the given text.
 *
 * On first call, downloads and loads the ONNX model (~600MB, cached).
 * Subsequent calls reuse the loaded model and run in ~100ms.
 *
 * The isQuery option is accepted for forward compatibility but does not
 * change behavior -- Qwen3 performs better without instruction prefixes.
 *
 * @param text - The text to embed.
 * @param options - Optional settings.
 * @param options.isQuery - Accepted for forward compatibility (no-op).
 * @returns 1024-dimensional normalized embedding as a number array.
 */
export async function generateEmbedding(
  text: string,
  options?: { isQuery?: boolean },
): Promise<number[]> {
  if (!extractor) {
    console.log('Downloading embedding model (one-time setup, ~600MB)...');
    extractor = await pipeline('feature-extraction', MODEL_ID, {
      quantized: true,
    });
    console.log('Embedding model ready.');
  }

  const input = text;
  const output = await extractor(input, { pooling: 'last_token', normalize: true });
  // output.data is a Float32Array; convert to plain number[]
  return Array.from(output.data as Float32Array);
}

/**
 * Get the embedding vector dimensionality.
 *
 * Always returns 1024 (fixed for Qwen3-Embedding-0.6B).
 * This is needed by downstream code (e.g. LSH hasher) to know the vector
 * size without calling the embedding model.
 */
export function getEmbeddingDims(): number {
  return EMBEDDING_DIM;
}

