        type: 'entity', name: 'John', entityType: 'person',
        observations: [
          'works at Acme Corp',       // lowercase verb -> "John works at Acme Corp"
          'John likes TypeScript',     // already starts with name -> unchanged
          'He prefers React',          // pronoun -> replaced: "John prefers React"
          'An avid hiker',             // uppercase start -> "John: An avid hiker"
        ],
      }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    assert(result.facts.length === 4, 'MCP: 4 observations -> 4 facts');
    assert(result.facts[0].text === 'John works at Acme Corp', 'MCP: lowercase verb prefixed with entity name');
    assert(result.facts[1].text === 'John likes TypeScript', 'MCP: already has entity name, unchanged');
    assert(result.facts[2].text === 'John prefers React', 'MCP: pronoun "He" replaced with entity name');
    assert(result.facts[3].text === 'John: An avid hiker', 'MCP: uppercase standalone sentence prefixed with colon');
  }

  // --- parses relations ---
  {
    const content = [
      JSON.stringify({ type: 'entity', name: 'John', entityType: 'person', observations: ['Developer'] }),
      JSON.stringify({ type: 'entity', name: 'Project Alpha', entityType: 'project', observations: ['Deadline March'] }),
      JSON.stringify({ type: 'relation', from: 'John', to: 'Project Alpha', relationType: 'works_on' }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    // 2 observations + 1 relation = 3 facts
    assert(result.facts.length === 3, 'MCP: 2 observations + 1 relation = 3 facts');
    assert(
      result.facts[2].text === 'John works on Project Alpha',
      'MCP: relation converted to human-readable text',
    );
    assert(result.facts[2].type === 'fact', 'MCP: relation type defaults to fact');
  }

  // --- later entity overrides earlier (append-only semantics) ---
  {
    const content = [
      JSON.stringify({ type: 'entity', name: 'John', entityType: 'person', observations: ['Old observation'] }),
      JSON.stringify({ type: 'entity', name: 'John', entityType: 'person', observations: ['New observation'] }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    // Only the later entity should be used (Map overwrites)
    assert(result.facts.length === 1, 'MCP: duplicate entity keeps only latest');
    assert(
      result.facts[0].text.includes('New observation'),
      'MCP: latest entity observations used',
    );
  }

  // --- warns on orphaned relations ---
  {
    const content = [
      JSON.stringify({ type: 'relation', from: 'Unknown', to: 'Also Unknown', relationType: 'knows' }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    const hasWarning = result.warnings.some((w) => w.includes('unknown entity'));
    assert(hasWarning, 'MCP: warns on orphaned relation with unknown entities');
    // Orphaned relation should not produce a fact
    assert(result.facts.length === 0, 'MCP: orphaned relation produces no facts');
  }

  // --- handles empty/blank lines in JSONL ---
  {
    const content = [
      '',
      JSON.stringify({ type: 'entity', name: 'Alice', entityType: 'person', observations: ['Likes coffee'] }),
      '   ',
      JSON.stringify({ type: 'entity', name: 'Bob', entityType: 'person', observations: ['Likes tea'] }),
      '',
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    assert(result.facts.length === 2, 'MCP: blank lines in JSONL are skipped');
    assert(result.errors.length === 0, 'MCP: blank lines do not produce errors');
  }

  // --- invalid JSON lines produce errors ---
  {
    const content = [
      JSON.stringify({ type: 'entity', name: 'Alice', entityType: 'person', observations: ['Valid'] }),
      'this is not json',
      JSON.stringify({ type: 'entity', name: 'Bob', entityType: 'person', observations: ['Also valid'] }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    assert(result.facts.length === 2, 'MCP: valid facts parsed despite invalid line');
    assert(result.errors.length === 1, 'MCP: one error for the invalid JSON line');
    assert(result.errors[0].includes('Line 2'), 'MCP: error references correct line number');
  }

  // --- entity type mapping ---
  {
    const content = [
      JSON.stringify({ type: 'entity', name: 'React', entityType: 'tool', observations: ['Frontend framework'] }),
      JSON.stringify({ type: 'entity', name: 'Launch', entityType: 'goal', observations: ['Ship by March'] }),
      JSON.stringify({ type: 'entity', name: 'Meeting', entityType: 'event', observations: ['Quarterly review'] }),
      JSON.stringify({ type: 'entity', name: 'PickedAWS', entityType: 'decision', observations: ['Over GCP'] }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    assert(result.facts[0].type === 'preference', 'MCP: "tool" entityType -> preference');
    assert(result.facts[1].type === 'goal', 'MCP: "goal" entityType -> goal');
    assert(result.facts[2].type === 'episodic', 'MCP: "event" entityType -> episodic');
    assert(result.facts[3].type === 'decision', 'MCP: "decision" entityType -> decision');
  }

  // --- no content and no file_path (and no default file) ---
  {
    const adapter = new MCPMemoryAdapter();
    // Pass a non-existent file_path to trigger the file read error path
    const result = await adapter.parse({ file_path: '/tmp/definitely-does-not-exist-totalreclaw-test.jsonl' });

    assert(result.facts.length === 0, 'MCP: missing file yields 0 facts');
    assert(result.errors.length > 0, 'MCP: missing file produces error');
  }

  // --- relation type humanization ---
  {
    const content = [
      JSON.stringify({ type: 'entity', name: 'A', entityType: 'person', observations: ['exists'] }),
      JSON.stringify({ type: 'entity', name: 'B', entityType: 'project', observations: ['exists'] }),
      JSON.stringify({ type: 'relation', from: 'A', to: 'B', relationType: 'MEMBER_OF' }),
    ].join('\n');

    const adapter = new MCPMemoryAdapter();
    const result = await adapter.parse({ content });

    const relFact = result.facts.find((f) => f.tags?.includes('relation'));
    assert(
      relFact?.text === 'A is a member of B',
      `MCP: MEMBER_OF humanized to "is a member of" (got: ${relFact?.text})`,
    );
  }

  // =========================================================================
  // BaseImportAdapter (via TestAdapter)
  // =========================================================================

  console.log('# BaseImportAdapter');

  const testAdapter = new TestAdapter();

  // --- text validation: minimum 3 chars ---
  {
    assert(testAdapter.testValidateFact({ text: '' }) === null, 'Base: empty text returns null');
    assert(testAdapter.testValidateFact({ text: 'ab' }) === null, 'Base: 2-char text returns null');
    assert(testAdapter.testValidateFact({ text: '   ' }) === null, 'Base: whitespace-only text returns null');
    assert(testAdapter.testValidateFact({ text: 'a  ' }) === null, 'Base: 1-char trimmed text returns null');

    const result = testAdapter.testValidateFact({ text: 'abc' });
    assert(result !== null, 'Base: 3-char text is valid');
    assert(result?.text === 'abc', 'Base: 3-char text preserved');
  }

  // --- text truncation at 512 chars ---
  {
    const longText = 'x'.repeat(600);
    const result = testAdapter.testValidateFact({ text: longText });

    assert(result !== null, 'Base: long text is valid');
    assert(result!.text.length === 512, `Base: text truncated to 512 chars (got ${result!.text.length})`);
  }

  // --- text is trimmed ---
  {
    const result = testAdapter.testValidateFact({ text: '  hello world  ' });
    assert(result !== null, 'Base: padded text is valid');
    assert(result!.text === 'hello world', 'Base: text is trimmed');
  }

  // --- type normalization ---
  {
    const validTypes = ['fact', 'preference', 'decision', 'episodic', 'goal', 'context', 'summary'] as const;

    for (const t of validTypes) {
      const result = testAdapter.testValidateFact({ text: 'test fact', type: t });
      assert(result?.type === t, `Base: type "${t}" preserved`);
    }

    const invalidResult = testAdapter.testValidateFact({ text: 'test fact', type: 'bogus' as any });
    assert(invalidResult?.type === 'fact', 'Base: invalid type defaults to "fact"');

    const missingResult = testAdapter.testValidateFact({ text: 'test fact' });
    assert(missingResult?.type === 'fact', 'Base: missing type defaults to "fact"');
  }

  // --- importance scale conversion (0-1 -> 1-10) ---
  {
    // 0-1 scale conversion
    const r0 = testAdapter.testValidateFact({ text: 'test fact', importance: 0.0 });
    assert(r0?.importance === 1, `Base: importance 0.0 -> 1 (got ${r0?.importance})`);

    const r05 = testAdapter.testValidateFact({ text: 'test fact', importance: 0.5 });
    assert(r05?.importance === 5, `Base: importance 0.5 -> 5 (got ${r05?.importance})`);

    const r1 = testAdapter.testValidateFact({ text: 'test fact', importance: 1.0 });
    assert(r1?.importance === 10, `Base: importance 1.0 -> 10 (got ${r1?.importance})`);

    const r03 = testAdapter.testValidateFact({ text: 'test fact', importance: 0.3 });
    assert(r03?.importance === 3, `Base: importance 0.3 -> 3 (got ${r03?.importance})`);

    const r08 = testAdapter.testValidateFact({ text: 'test fact', importance: 0.8 });
    assert(r08?.importance === 8, `Base: importance 0.8 -> 8 (got ${r08?.importance})`);
  }

  // --- importance already on 1-10 scale ---
  {
    const r5 = testAdapter.testValidateFact({ text: 'test fact', importance: 5 });
    assert(r5?.importance === 5, `Base: importance 5 stays 5 (got ${r5?.importance})`);

    const r10 = testAdapter.testValidateFact({ text: 'test fact', importance: 10 });
    assert(r10?.importance === 10, `Base: importance 10 stays 10 (got ${r10?.importance})`);

    const r7 = testAdapter.testValidateFact({ text: 'test fact', importance: 7 });
    assert(r7?.importance === 7, `Base: importance 7 stays 7 (got ${r7?.importance})`);
  }

  // --- importance clamping ---
  {
    const rNeg = testAdapter.testValidateFact({ text: 'test fact', importance: -5 });
    assert(rNeg?.importance === 1, `Base: importance -5 clamped to 1 (got ${rNeg?.importance})`);

    const rHuge = testAdapter.testValidateFact({ text: 'test fact', importance: 100 });
    assert(rHuge?.importance === 10, `Base: importance 100 clamped to 10 (got ${rHuge?.importance})`);
  }

  // --- importance default ---
  {
    const rDefault = testAdapter.testValidateFact({ text: 'test fact' });
    assert(rDefault?.importance === 5, `Base: missing importance defaults to 5 (got ${rDefault?.importance})`);
  }

  // --- source defaults to adapter's source ---
  {
    const result = testAdapter.testValidateFact({ text: 'test fact' });
    assert(result?.source === 'mem0', 'Base: source defaults to adapter source');

    const withSource = testAdapter.testValidateFact({ text: 'test fact', source: 'mcp-memory' });
    assert(withSource?.source === 'mcp-memory', 'Base: explicit source preserved');
  }

  // --- validateFacts batch ---
  {
    const rawFacts: Partial<NormalizedFact>[] = [
      { text: 'Valid fact one' },
      { text: '' },               // invalid
      { text: 'Valid fact two' },
      { text: 'xy' },             // too short
      { text: 'Valid fact three' },
    ];

    const { facts, invalidCount } = testAdapter.testValidateFacts(rawFacts);
    assert(facts.length === 3, `Base: validateFacts keeps 3 valid out of 5 (got ${facts.length})`);
    assert(invalidCount === 2, `Base: validateFacts counts 2 invalid (got ${invalidCount})`);
  }

  // =========================================================================
  // getAdapter factory
  // =========================================================================

  console.log('# getAdapter factory');

  // --- valid sources ---
  {
    const mem0 = getAdapter('mem0');
    assert(mem0 instanceof Mem0Adapter, 'getAdapter("mem0") returns Mem0Adapter');

    const mcp = getAdapter('mcp-memory');
    assert(mcp instanceof MCPMemoryAdapter, 'getAdapter("mcp-memory") returns MCPMemoryAdapter');
  }

  // --- unknown source throws ---
  {
    assertThrows(
      () => getAdapter('nonexistent' as ImportSource),
      'getAdapter throws on unknown source',
    );
  }

  // --- error message lists valid sources ---
  {
    try {
      getAdapter('bogus' as ImportSource);
      assert(false, 'getAdapter should throw for bogus source');
    } catch (e: unknown) {
      const msg = (e as Error).message;
      assert(msg.includes('mem0'), 'getAdapter error lists "mem0" as valid source');
      assert(msg.includes('mcp-memory'), 'getAdapter error lists "mcp-memory" as valid source');
    }
  }

  // =========================================================================
  // Summary
  // =========================================================================

  console.log(`\n1..${testNum}`);
  console.log(`# pass: ${passed}`);
  console.log(`# fail: ${failed}`);

  if (failed > 0) {
    console.log('\nFAILED');
    process.exit(1);
  } else {
    console.log('\nALL TESTS PASSED');
    process.exit(0);
  }
}

runTests().catch((err) => {
  console.error('Test runner failed:', err);
  process.exit(1);
});

export { BaseImportAdapter } from './base-adapter.js';
export * from './types.js';
export { Mem0Adapter } from './mem0-adapter.js';
export { MCPMemoryAdapter } from './mcp-memory-adapter.js';

import type { ImportSource } from './types.js';
import { Mem0Adapter } from './mem0-adapter.js';
import { MCPMemoryAdapter } from './mcp-memory-adapter.js';
import type { BaseImportAdapter } from './base-adapter.js';

const ADAPTERS: Partial<Record<ImportSource, () => BaseImportAdapter>> = {
  'mem0': () => new Mem0Adapter(),
  'mcp-memory': () => new MCPMemoryAdapter(),
};

export function getAdapter(source: ImportSource): BaseImportAdapter {
  const factory = ADAPTERS[source];
  if (!factory) {
    throw new Error(`Unknown import source: ${source}. Valid sources: ${Object.keys(ADAPTERS).join(', ')}`);
  }
  return factory();
}

import { BaseImportAdapter } from './base-adapter.js';
import type {
  ImportSource,
  NormalizedFact,
  AdapterParseResult,
  ProgressCallback,
} from './types.js';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

/**
 * MCP Memory Server entity record.
 */
interface MCPEntity {
  type: 'entity';
  name: string;
  entityType: string;
  observations: string[];
}

/**
 * MCP Memory Server relation record.
 */
interface MCPRelation {
  type: 'relation';
  from: string;
  to: string;
  relationType: string;
}

type MCPRecord = MCPEntity | MCPRelation;

/**
 * Entity type mapping to TotalReclaw fact types.
 */
const ENTITY_TYPE_MAP: Record<string, NormalizedFact['type']> = {
  person: 'fact',
  project: 'fact',
  organization: 'fact',
  tool: 'preference',
  technology: 'preference',
  preference: 'preference',
  goal: 'goal',
  event: 'episodic',
  decision: 'decision',
};

export class MCPMemoryAdapter extends BaseImportAdapter {
  readonly source: ImportSource = 'mcp-memory';
  readonly displayName = 'MCP Memory Server';

  async parse(
    input: { content?: string; file_path?: string },
    onProgress?: ProgressCallback,
  ): Promise<AdapterParseResult> {
    const warnings: string[] = [];
    const errors: string[] = [];

    let content: string;

    if (input.content) {
      content = input.content;
    } else if (input.file_path) {
      try {
        const resolvedPath = input.file_path.replace(/^~/, os.homedir());
        content = fs.readFileSync(resolvedPath, 'utf-8');
      } catch (e) {
        errors.push(`Failed to read file: ${e instanceof Error ? e.message : 'Unknown error'}`);
        return { facts: [], warnings, errors };
      }
    } else {
      // Try default MCP memory path
      const defaultPath = path.join(os.homedir(), '.mcp-memory', 'memory.jsonl');
      try {
        content = fs.readFileSync(defaultPath, 'utf-8');
        warnings.push(`Using default MCP memory path: ${defaultPath}`);
      } catch {
        errors.push(
          'No content, file_path, or file at default path (~/.mcp-memory/memory.jsonl). ' +
          'Provide the memory.jsonl content or file path.',
        );
        return { facts: [], warnings, errors };
      }
    }

    // Parse JSONL records
    const records = this.parseJSONL(content, errors);

    if (onProgress) {
      onProgress({
        current: 0,
        total: records.length,
        phase: 'parsing',
        message: `Parsing ${records.length} MCP Memory records...`,
      });
    }

    // Separate entities and relations
    const entities = new Map<string, MCPEntity>();
    const relations: MCPRelation[] = [];

    for (const record of records) {
      if (record.type === 'entity') {
        // Later entities override earlier ones (append-only file)
        entities.set(record.name, record);
      } else if (record.type === 'relation') {
        relations.push(record);
      }
    }

    // Convert entities to facts
    const rawFacts: Partial<NormalizedFact>[] = [];
    let entityIndex = 0;

    for (const [name, entity] of entities) {
      const factType = ENTITY_TYPE_MAP[entity.entityType.toLowerCase()] || 'fact';

      for (const observation of entity.observations) {
        // Prefix observation with entity name for context
        // "Works at Acme Corp" -> "John works at Acme Corp"
        const text = this.contextualizeObservation(name, observation);

        rawFacts.push({
          text,
          type: factType,
          importance: 6,
          source: 'mcp-memory',
          sourceId: `${name}:${entityIndex}`,
          tags: [entity.entityType],
        });
        entityIndex++;
      }

      if (onProgress) {
        onProgress({
          current: rawFacts.length,
          total: rawFacts.length + relations.length,
          phase: 'parsing',
          message: `Parsed ${rawFacts.length} facts from entities...`,
        });
      }
    }

    // Convert relations to facts
    for (const rel of relations) {
      // Only create a fact if both entities exist
      if (!entities.has(rel.from) || !entities.has(rel.to)) {
        warnings.push(`Relation references unknown entity: ${rel.from} -> ${rel.to}`);
        continue;
      }

      const text = `${rel.from} ${this.humanizeRelationType(rel.relationType)} ${rel.to}`;

      rawFacts.push({
        text,
        type: 'fact',
        importance: 5,
        source: 'mcp-memory',
        sourceId: `rel:${rel.from}:${rel.relationType}:${rel.to}`,
        tags: ['relation'],
      });
    }

    const { facts, invalidCount } = this.validateFacts(rawFacts);

    if (invalidCount > 0) {
      warnings.push(`${invalidCount} observations had invalid/empty text and were skipped`);
    }

    return {
      facts,
      warnings,
      errors,
      source_metadata: {
        entities_count: entities.size,
        relations_count: relations.length,
        observations_total: rawFacts.length,
      },
    };
  }

  /**
   * Parse JSONL content into records.
   */
  private parseJSONL(content: string, errors: string[]): MCPRecord[] {
    const records: MCPRecord[] = [];
    const lines = content.split('\n').filter((line) => line.trim().length > 0);

    for (let i = 0; i < lines.length; i++) {
      try {
        const record = JSON.parse(lines[i]);
        if (record.type === 'entity' || record.type === 'relation') {
          records.push(record as MCPRecord);
        } else {
          // Unknown record type — skip silently (future-proofing)
        }
      } catch {
        errors.push(`Line ${i + 1}: Invalid JSON — skipped`);
      }
    }

    return records;
  }

  /**
   * Add entity context to an observation.
   *
   * Heuristic: if the observation already starts with the entity name
   * (case-insensitive) or a pronoun, return as-is. Otherwise prefix.
   *
   * Examples:
   *  - ("John", "Works at Acme Corp") -> "John works at Acme Corp"
   *  - ("John", "John likes TypeScript") -> "John likes TypeScript" (no double prefix)
   *  - ("John", "He prefers React") -> "John prefers React"
   */
  private contextualizeObservation(entityName: string, observation: string): string {
    const obsLower = observation.toLowerCase().trim();
    const nameLower = entityName.toLowerCase();

    // Already starts with the entity name
    if (obsLower.startsWith(nameLower)) {
      return observation.trim();
    }

    // Starts with a pronoun — replace it
    const pronouns = ['he ', 'she ', 'they ', 'it ', 'his ', 'her ', 'their ', 'its '];
    for (const pronoun of pronouns) {
      if (obsLower.startsWith(pronoun)) {
        return entityName + ' ' + observation.trim().slice(pronoun.length);
      }
    }

    // Starts with a verb (lowercase first word) — prefix entity name
    const firstChar = observation.trim()[0];
    if (firstChar && firstChar === firstChar.toLowerCase()) {
      return `${entityName} ${observation.trim()}`;
    }

    // Observation is a standalone sentence — prefix with "About {entity}: "
    return `${entityName}: ${observation.trim()}`;
  }

  /**
   * Convert relation type slug to human-readable text.
   *
   * "works_on" -> "works on"
   * "MEMBER_OF" -> "is a member of"
   */
  private humanizeRelationType(relationType: string): string {
    const slug = relationType.toLowerCase().replace(/_/g, ' ');

    // Common relation type mappings
    const mappings: Record<string, string> = {
      'works on': 'works on',
      'works at': 'works at',
      'member of': 'is a member of',
      'belongs to': 'belongs to',
      'created by': 'was created by',
      'depends on': 'depends on',
      'uses': 'uses',
      'knows': 'knows',
      'related to': 'is related to',
      'part of': 'is part of',
      'friend of': 'is friends with',
      'manages': 'manages',
      'reports to': 'reports to',
      'located in': 'is located in',
      'lives in': 'lives in',
    };

    return mappings[slug] || slug;
  }
}

import { BaseImportAdapter } from './base-adapter.js';
import type {
  ImportSource,
  NormalizedFact,
  AdapterParseResult,
  ProgressCallback,
} from './types.js';

/**
 * Mem0 memory structure from their API/export.
 */
interface Mem0Memory {
  id: string;
  memory: string;
  hash?: string;
  metadata?: {
    category?: string;
    created_at?: string;
    updated_at?: string;
  };
  user_id?: string;
  agent_id?: string;
  categories?: string[];
}

interface Mem0ApiResponse {
  results: Mem0Memory[];
  next?: string; // pagination cursor
  total?: number;
}

interface Mem0ExportFile {
  export_date?: string;
  user_id?: string;
  memories: Mem0Memory[];
}

/**
 * Category mapping from Mem0 categories to TotalReclaw types.
 */
const CATEGORY_MAP: Record<string, NormalizedFact['type']> = {
  preference: 'preference',
  preferences: 'preference',
  like: 'preference',
  dislike: 'preference',
  fact: 'fact',
  personal: 'fact',
  biographical: 'fact',
  decision: 'decision',
  goal: 'goal',
  objective: 'goal',
  experience: 'episodic',
  event: 'episodic',
  memory: 'episodic',
};

export class Mem0Adapter extends BaseImportAdapter {
  readonly source: ImportSource = 'mem0';
  readonly displayName = 'Mem0';

  async parse(
    input: { content?: string; api_key?: string; source_user_id?: string; api_url?: string },
    onProgress?: ProgressCallback,
  ): Promise<AdapterParseResult> {
    const warnings: string[] = [];
    const errors: string[] = [];

    let memories: Mem0Memory[];

    if (input.content) {
      // Parse from pasted content or export file
      memories = this.parseExportContent(input.content, errors);
    } else if (input.api_key) {
      // Fetch from Mem0 API
      memories = await this.fetchFromApi(
        input.api_key,
        input.source_user_id,
        input.api_url,
        onProgress,
        errors,
      );
    } else {
      errors.push('Mem0 import requires either content (export file) or api_key');
      return { facts: [], warnings, errors };
    }

    if (onProgress) {
      onProgress({
        current: 0,
        total: memories.length,
        phase: 'parsing',
        message: `Parsing ${memories.length} Mem0 memories...`,
      });
    }

    // Convert Mem0 memories to NormalizedFacts
    const rawFacts: Partial<NormalizedFact>[] = memories.map((mem) => ({
      text: mem.memory,
      type: this.mapCategory(mem.categories, mem.metadata?.category),
      importance: 6, // Mem0 doesn't provide importance — default to 6 (above threshold)
      source: 'mem0' as ImportSource,
      sourceId: mem.id,
      sourceTimestamp: mem.metadata?.updated_at || mem.metadata?.created_at,
      tags: mem.categories || [],
    }));

    const { facts, invalidCount } = this.validateFacts(rawFacts);

    if (invalidCount > 0) {
      warnings.push(`${invalidCount} memories had invalid/empty text and were skipped`);
    }

    return { facts, warnings, errors, source_metadata: { total_from_source: memories.length } };
  }

  /**
   * Parse Mem0 export file or pasted JSON.
   */
  private parseExportContent(content: string, errors: string[]): Mem0Memory[] {
    try {
      const data = JSON.parse(content.trim());

      // Handle export file format: { memories: [...] }
      if (data.memories && Array.isArray(data.memories)) {
        return data.memories;
      }

      // Handle API response format: { results: [...] }
      if (data.results && Array.isArray(data.results)) {
        return data.results;
      }

      // Handle bare array
      if (Array.isArray(data)) {
        return data;
      }

      errors.push('Unrecognized Mem0 format. Expected { memories: [...] }, { results: [...] }, or bare array.');
      return [];
    } catch (e) {
      errors.push(`Failed to parse Mem0 JSON: ${e instanceof Error ? e.message : 'Unknown error'}`);
      return [];
    }
  }

  /**
   * Fetch all memories from Mem0 API with pagination.
   */
  private async fetchFromApi(
    apiKey: string,
    sourceUserId?: string,
    apiUrl?: string,
    onProgress?: ProgressCallback,
    errors?: string[],
  ): Promise<Mem0Memory[]> {
    const baseUrl = apiUrl || 'https://api.mem0.ai';
    const allMemories: Mem0Memory[] = [];
    let page = 1;
    const pageSize = 100;
    let hasMore = true;

    while (hasMore) {
      try {
        const url = new URL(`${baseUrl}/v1/memories/`);
        url.searchParams.set('page', String(page));
        url.searchParams.set('page_size', String(pageSize));
        if (sourceUserId) {
          url.searchParams.set('user_id', sourceUserId);
        }

        const response = await fetch(url.toString(), {
          headers: {
            Authorization: `Token ${apiKey}`,
            'Content-Type': 'application/json',
          },
        });

        if (!response.ok) {
          const errorText = await response.text();
          errors?.push(`Mem0 API error (${response.status}): ${errorText.slice(0, 200)}`);
          break;
        }

        const data: Mem0ApiResponse = await response.json();
        const memories = data.results || [];
        allMemories.push(...memories);

        if (onProgress) {
          onProgress({
            current: allMemories.length,
            total: data.total || allMemories.length,
            phase: 'fetching',
            message: `Fetched ${allMemories.length} memories from Mem0...`,
          });
        }

        hasMore = memories.length === pageSize;
        page++;

        // Safety limit: 10,000 memories max
        if (allMemories.length >= 10_000) {
          errors?.push('Reached 10,000 memory limit. Some memories may not have been fetched.');
          break;
        }
      } catch (e) {
        errors?.push(`Mem0 API fetch error: ${e instanceof Error ? e.message : 'Unknown error'}`);
        break;
      }
    }

    return allMemories;
  }

  /**
   * Map Mem0 category to TotalReclaw fact type.
   */
  private mapCategory(
    categories?: string[],
    singleCategory?: string,
  ): NormalizedFact['type'] {
    const allCategories = [
      ...(categories || []),
      ...(singleCategory ? [singleCategory] : []),
    ];

    for (const cat of allCategories) {
      const mapped = CATEGORY_MAP[cat.toLowerCase()];
      if (mapped) return mapped;
    }

    return 'fact'; // default
  }
}

/**
 * Normalized fact — the common format all adapters produce.
 * Maps directly to what storeExtractedFacts() / client.remember() expect.
 */
export interface NormalizedFact {
  /** The atomic fact text (max 512 chars) */
  text: string;
  /** Fact type matching TotalReclaw's taxonomy */
  type: 'fact' | 'preference' | 'decision' | 'episodic' | 'goal' | 'context' | 'summary';
  /** Importance score 1-10 */
  importance: number;
  /** Original source system */
  source: ImportSource;
  /** Original ID in the source system (for traceability) */
  sourceId?: string;
  /** Original timestamp from source */
  sourceTimestamp?: string;
  /** Additional tags */
  tags?: string[];
}

export type ImportSource = 'mem0' | 'mcp-memory' | 'memoclaw' | 'generic-json' | 'generic-csv';

/**
 * What the user passes to the import tool.
 */
export interface ImportFromInput {
  /** Which source to import from */
  source: ImportSource;
  /** For API-based sources: the API key or auth token */
  api_key?: string;
  /** For API-based sources: the user/agent ID in the source system */
  source_user_id?: string;
  /** For file-based sources: the file content (pasted or read) */
  content?: string;
  /** For file-based sources: path to the file on disk */
  file_path?: string;
  /** Optional: target namespace in TotalReclaw */
  namespace?: string;
  /** Optional: dry run — parse and report without storing */
  dry_run?: boolean;
  /** Optional: API base URL override (for self-hosted instances) */
  api_url?: string;
}

/**
 * Result of an import operation.
 */
export interface ImportResult {
  success: boolean;
  source: ImportSource;
  /** Total facts found in source */
  total_found: number;
  /** Facts successfully imported */
  imported: number;
  /** Facts skipped (duplicates via content fingerprint) */
  skipped_duplicate: number;
  /** Facts skipped (validation errors) */
  skipped_invalid: number;
  /** Individual errors */
  errors: Array<{ index: number; text_preview: string; error: string }>;
  /** Warnings */
  warnings: string[];
  /** Unique import run ID */
  import_id: string;
  /** Duration in ms */
  duration_ms: number;
}

/**
 * Progress callback for long-running imports.
 */
export type ProgressCallback = (progress: {
  current: number;
  total: number;
  phase: 'fetching' | 'parsing' | 'storing';
  message: string;
}) => void;

/**
 * Adapter parse result — returned by each adapter's parse method.
 */
export interface AdapterParseResult {
  facts: NormalizedFact[];
  warnings: string[];
  errors: string[];
  /** Metadata about the source (for logging) */
  source_metadata?: Record<string, unknown>;
}

/**
 * TotalReclaw Plugin for OpenClaw
 *
 * Registers runtime tools so OpenClaw can execute TotalReclaw operations:
 *   - totalreclaw_remember     -- store an encrypted memory
 *   - totalreclaw_recall       -- search and decrypt memories
 *   - totalreclaw_forget       -- soft-delete a memory
 *   - totalreclaw_export       -- export all memories (JSON or Markdown)
 *   - totalreclaw_status       -- check billing/subscription status
 *   - totalreclaw_consolidate  -- scan and merge near-duplicate memories
 *   - totalreclaw_import_from  -- import memories from other tools (Mem0, MCP Memory, etc.)
 *   - totalreclaw_upgrade      -- create Stripe checkout for Pro upgrade
 *   - totalreclaw_migrate      -- migrate testnet memories to mainnet after Pro upgrade
 *
 * Also registers a `before_agent_start` hook that automatically injects
 * relevant memories into the agent's context.
 *
 * All data is encrypted client-side with AES-256-GCM. The server never
 * sees plaintext.
 */

