console.log('# BM25 Scoring');

{
  // Simple single-document scenario
  const queryTerms = ['alex', 'works'];
  const docTerms = ['alex', 'works', 'nexus', 'labs'];
  const avgDocLen = 4;
  const docCount = 1;
  const termDocFreqs = new Map<string, number>([
