  assert(score > 0, `BM25: matching query gets positive score (${score.toFixed(4)})`);
}

{
  // No overlap
  const queryTerms = ['python', 'programming'];
  const docTerms = ['alex', 'works', 'nexus', 'labs'];
  const avgDocLen = 4;
  const docCount = 1;
  const termDocFreqs = new Map<string, number>([
